package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen2Test {

    @Test
    public void testOperate_Success() {
        // Setup a 2x3 matrix
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {BigDecimal.ONE, BigDecimal.valueOf(2), BigDecimal.valueOf(3)},
            {BigDecimal.valueOf(4), BigDecimal.valueOf(5), BigDecimal.valueOf(6)}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector of length 3
        // [ 1, 0, 2 ]
        BigDecimal[] v = {
            BigDecimal.ONE,
            BigDecimal.ZERO,
            BigDecimal.valueOf(2)
        };

        // Expected result:
        // Row 0: (1*1) + (2*0) + (3*2) = 1 + 0 + 6 = 7
        // Row 1: (4*1) + (5*0) + (6*2) = 4 + 0 + 12 = 16
        BigDecimal[] expected = {
            BigDecimal.valueOf(7),
            BigDecimal.valueOf(16)
        };

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperate_WrongLength_ThrowsException() {
        // Setup a 2x2 matrix
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);

        // Provide a vector of length 3 instead of 2
        BigDecimal[] v = {BigDecimal.ONE, BigDecimal.ONE, BigDecimal.ONE};

        matrix.operate(v);
    }

    @Test
    public void testOperate_SingleElementMatrix() {
        // Setup a 1x1 matrix
        BigDecimal[][] data = {{BigDecimal.valueOf(5)}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {BigDecimal.valueOf(2)};
        BigDecimal[] expected = {BigDecimal.valueOf(10)};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_ZeroMatrix() {
        // Setup a 2x2 zero matrix
        BigMatrixImpl matrix = new BigMatrixImpl(2, 2);
        // Default constructor or dimension constructor usually initializes to zero or requires manual setting
        // Based on standard math libs, we assume dimensions are set.
        // If the constructor doesn't init data, we use the array constructor.
        BigDecimal[][] data = {
            {BigDecimal.ZERO, BigDecimal.ZERO},
            {BigDecimal.ZERO, BigDecimal.ZERO}
        };
        matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {BigDecimal.TEN, BigDecimal.TEN};
        BigDecimal[] expected = {BigDecimal.ZERO, BigDecimal.ZERO};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_NegativeValues() {
        BigDecimal[][] data = {
            {BigDecimal.valueOf(-1), BigDecimal.valueOf(2)},
            {BigDecimal.valueOf(3), BigDecimal.valueOf(-4)}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        BigDecimal[] v = {BigDecimal.valueOf(2), BigDecimal.valueOf(-1)};

        // Row 0: (-1 * 2) + (2 * -1) = -2 - 2 = -4
        // Row 1: (3 * 2) + (-4 * -1) = 6 + 4 = 10
        BigDecimal[] expected = {BigDecimal.valueOf(-4), BigDecimal.valueOf(10)};

        BigDecimal[] result = matrix.operate(v);
        Assert.assertArrayEquals(expected, result);
    }
}
